"""Stable high-level facade (client.sites / servers / backups / workflows). Written once, async-native.

The sync twin is generated. Everything is async-native (fcctl._async.backups / workflows) over the
client's own central/pilot clients; no thread shims.

Guard model (library users)
---------------------------
Destructive facade methods are guarded BY DEFAULT, matching the CLI policy registry (fcctl.policy.REGISTRY:
kind "destructive" -> two-person approval). Calling one does not execute it: it files and returns a
`fcctl.guard.PendingApproval`; an approver must approve it, and approving executes the raw op.

  * `Sites.drop`      (site.drop, destructive)      guarded
  * `Backups.restore` (backup.restore, destructive) guarded

Two explicit ways past the guard:
  * `owned_by_workflow=<workflow_id>`: ownership check (the journal must show that workflow created the
    site); passing proceeds unguarded, failing raises PolicyDenied. For workflow-owned sites only.
  * `unsafe=True`: perform the raw operation with NO guard and NO ownership check. An audit entry
    (outcome "unsafe", extra unsafe=True) is appended to the hash-chained audit log first, and the call
    fails closed if that entry cannot be written. Use only from trusted code.

Left unguarded: read/write ops, `Servers.resize` (registry kind "cost": the CLI asks for --confirm, which
has no library equivalent; it already refuses disk shrink) and `Workflows.provision_site` (creates, and only
restores onto a site the workflow itself creates).

The guard is enforced at THIS facade only. Direct low-level calls such as `client.pilot(server).post(...)`
or `client.central.call(...)` bypass it by design (they are the raw transport).
"""
from __future__ import annotations

from ..region import default_region
from .pilot import seg

import os
import warnings
from typing import Any
from pathlib import Path

from ..facade_types import BackupSource
from ..errors import DiskShrinkRefused, FcError, PolicyDenied, UsageError
from . import siteadmin as _siteadmin

M = "central.api.servers."
CATALOG = "central.billing.api.dashboard.catalog."
RESTORE_PARTS = ("database", "public", "private", "config")


def _disk(d) -> float | None:
    """Disk GB from a server overview, composed config or catalog plan row (None when unknown)."""
    if not isinstance(d, dict):
        return None
    plan: dict = d["plan"] if isinstance(d.get("plan"), dict) else {}
    for v in (d.get("disk_gigabytes"), d.get("disk_gb"), d.get("disk"), plan.get("disk")):
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v)
    for inc in d.get("includes") or []:
        if isinstance(inc, dict) and inc.get("resource_type") == "Disk" and isinstance(inc.get("quantity"), (int, float)):
            return float(inc["quantity"])
    return None


def _plan_rows(plans) -> list:
    """Flatten get_eligible_plans' {"plans": {sub_category: [rows]}} (or a bare list) into rows."""
    if isinstance(plans, dict):
        plans = plans.get("plans") or []
    if isinstance(plans, dict):
        return [r for rows in plans.values() if isinstance(rows, list) for r in rows]
    return list(plans) if isinstance(plans, list) else []


def _journal():
    from ..journal import Journal
    return Journal(Path(os.environ.get("FCCTL_HOME") or Path.home() / ".fcctl") / "journal")


def _audit_unsafe(op, target):
    """Append a hash-chained audit row for an `unsafe=True` facade call (fails closed if it cannot be written)."""
    from .. import config
    from ..audit import AuditLog
    AuditLog(config.home() / "audit" / "audit.jsonl").append(
        actor="library", op=op, target=str(target), outcome="unsafe", unsafe=True)


def _check_owned(workflow_id, site, journal, policy, what):
    from .workflows.provision import is_workflow_owned
    j = journal or _journal()
    if not is_workflow_owned(j, workflow_id, site, j.now(), policy):
        raise PolicyDenied(f"{what} on {site} is not owned by workflow {workflow_id}")


class Sites:
    def __init__(self, client):
        self._c = client

    def _set(self, server, site, on):
        return self._c.pilot(server).patch(
            f"/sites/{seg(site)}/configuration", {"maintenance_mode": int(on), "pause_scheduler": int(on)})

    def suspend(self, server: str, site: str):
        """maintenance_mode=1 and pause_scheduler=1 (PATCH site configuration, sync, no task)."""
        return self._set(server, site, True)

    def resume(self, server: str, site: str):
        return self._set(server, site, False)

    def create(self, server: str, name: str, apps: list[str], idempotency_key: str | None = None):
        """Create a site (Pilot POST /sites); returns the 202 task dict. Same call provision uses."""
        from . import sites
        return sites.create_site(self._c.pilot(server), name, list(apps), key=idempotency_key)

    def list(self, server: str):
        from . import sites
        return sites.list_sites(self._c.pilot(server))

    def login_link(self, server: str, site: str):
        """Pilot POST /sites/<site>/login -> response (contains the login url)."""
        return self._c.pilot(server).post(f"/sites/{seg(site)}/login")

    def drop(self, server: str, site: str, owned_by_workflow: str | None = None, journal=None,
                   policy: str = "guarded", no_backup: bool = False, unsafe: bool = False):
        """DESTRUCTIVE. Guarded (PendingApproval) unless owned_by_workflow passes the ownership check
        (journal shows that workflow created `site`); a non-passing owned_by_workflow raises PolicyDenied.
        unsafe=True skips the guard and ownership check (audited)."""
        p = self._c.pilot(server)
        if unsafe:
            _audit_unsafe("site.drop", site)
            from . import sites
            return sites.drop_site(p, site, no_backup=no_backup)
        if owned_by_workflow:
            _check_owned(owned_by_workflow, site, journal, policy, "drop")
            from . import sites
            return sites.drop_site(p, site, no_backup=no_backup)
        from .. import sites as legacy
        return legacy.drop_site(p, site, no_backup=no_backup)

    def admin(self, server: str, site: str):
        """Open an Administrator SiteAdminClient (mints a Pilot login link). Caller must `await aclose()`."""
        return _siteadmin.open_admin(self._c, server, site)


class Servers:
    def __init__(self, client):
        self._c = client

    def resize(self, server: str, plan: str, **extra):
        """POST resize_server; refuses a disk shrink (DiskShrinkRefused) when both disks are known.

        The pre-check mirrors the FC dashboard's resize dialog: the server overview gives the region and
        disk, get_composed_config gives the subscription, and the billing catalog's get_eligible_plans
        (cluster + exclude_subscription + for_resize=1) gives the target plan's Disk allowance. An explicit
        disk_gigabytes in `extra` is the disk the resize asks for. If the plan data cannot be read the
        check fails open with a warning; Central itself still refuses a smaller disk.
        """
        c = self._c.central
        overview = c.call("GET", M + "server_overview", params={"resource_id": server})
        if isinstance(overview, dict) and isinstance(overview.get("server"), dict):
            overview = overview["server"]  # Central wraps the row: {"server": {...}}
        cur = _disk(overview)
        new = extra.get("disk_gigabytes")
        new = float(new) if isinstance(new, (int, float)) and not isinstance(new, bool) else None
        if new is None or cur is None:
            try:
                plan_disk, cfg_disk = self._plan_disk(server, plan, overview)
                new = plan_disk if new is None else new
                cur = cfg_disk if cur is None else cur
            except FcError as e:
                warnings.warn(f"fcctl: disk-shrink pre-check skipped for {server} ({e}); resizing anyway",
                              RuntimeWarning, stacklevel=2)
            else:
                if cur is None or new is None:
                    warnings.warn(f"fcctl: disk-shrink pre-check skipped for {server}: "
                                  f"{'current disk' if cur is None else 'plan ' + plan + ' disk'} unknown; resizing anyway",
                                  RuntimeWarning, stacklevel=2)
        if cur is not None and new is not None and new < cur:
            raise DiskShrinkRefused(f"plan {plan} disk {new:g}GB < current {cur:g}GB; disk shrink is not allowed")
        return c.call("POST", M + "resize_server", json={"resource_id": server, "plan": plan, **extra})

    def _plan_disk(self, server: str, plan: str, overview) -> tuple[float | None, float | None]:
        """(target plan's Disk GB, current disk GB from get_composed_config)."""
        c = self._c.central
        region = (overview.get("region") if isinstance(overview, dict) else None) or default_region()
        cfg = c.call("GET", CATALOG + "get_composed_config", params={"server": server})
        sub = cfg.get("subscription") if isinstance(cfg, dict) else None
        params: dict[str, Any] = {"cluster": region}
        if sub:
            params.update(exclude_subscription=sub, for_resize=1)
        rows = _plan_rows(c.call("GET", CATALOG + "get_eligible_plans", params=params))
        new = next((_disk(p) for p in rows if isinstance(p, dict) and plan in (p.get("plan"), p.get("name"))), None)
        return new, _disk(cfg)


class Backups:
    def __init__(self, client):
        self._c = client

    def download_links(self, server: str, site: str, ts: str):
        return self._c.pilot(server).get(f"/sites/{seg(site)}/backups/{seg(ts)}/download-links")

    def restore(self, server: str, site: str, from_upload=None, from_site_backup=None,
                      owned_by_workflow: str | None = None, journal=None, policy: str = "guarded",
                      skip_failing_patches: bool = False, unsafe: bool = False):
        """Overwrites `site`. Guarded (returns PendingApproval) unless owned_by_workflow passes D11
        (journal shows that workflow created `site`); a non-passing owned_by_workflow raises PolicyDenied.

        unsafe=True skips the guard and ownership check (audited).

        from_upload: upload_id str or {"upload_id", "parts"}; from_site_backup: {"server","site","ts"[,"parts"]}.
        """
        if bool(from_upload) == bool(from_site_backup):
            raise UsageError("pass exactly one of from_upload / from_site_backup")
        p = self._c.pilot(server)
        if unsafe:
            _audit_unsafe("backup.restore", site)
            owned_by_workflow = owned_by_workflow or "unsafe"
        elif owned_by_workflow:
            _check_owned(owned_by_workflow, site, journal, policy, "restore")
        if from_upload:
            u = {"upload_id": from_upload} if isinstance(from_upload, str) else dict(from_upload)
            parts = list(u.get("parts") or RESTORE_PARTS)
            if owned_by_workflow:
                body = {"parts": parts, "skip_failing_patches": skip_failing_patches, "upload_id": u["upload_id"]}
                return p.post(f"/sites/{seg(site)}/actions/restore", body)
            from .. import backups as legacy
            return legacy.restore(p, site, parts=tuple(parts), upload_id=u["upload_id"],
                                  skip_failing_patches=skip_failing_patches)
        s = dict(from_site_backup)
        from . import backups as core
        src = self._c.pilot(s["server"])
        kw: dict[str, Any] = {"skip_failing_patches": skip_failing_patches}
        if s.get("parts"):
            kw["parts"] = tuple(s["parts"])
        if owned_by_workflow:
            return core.restore_from_site_backup(src, s["site"], s["ts"], p, site,
                                                       owned_by_workflow=owned_by_workflow, **kw)
        from .. import backups as legacy
        up = core.upload_from_site_backup(src, s["site"], s["ts"], p, site, **kw)
        return legacy.restore(p, site, parts=tuple(up["parts"]), upload_id=up["upload_id"],
                              skip_failing_patches=skip_failing_patches)


class Workflows:
    def __init__(self, client):
        self._c = client

    def provision_site(self, *, server: str, site: str, from_backup=None, journal=None, **kw):
        """Build a ProvisionRun (not yet executed); `await run.wait()` on the async client, `run.wait()` on the sync one.

        from_backup: facade BackupSource(profile, server, site, ts) or a workflows.types backup source."""
        from .workflows import provision
        from .workflows.types import BackupSource as WfBackup
        central, pilot = self._c.central, self._c.pilot(server)
        if isinstance(from_backup, BackupSource):
            src_pilot = self._c.pilot(from_backup.server)
            kw.setdefault("api", provision.LiveApi(pilot, central, source_pilot=src_pilot))
            from_backup = WfBackup(from_backup.profile, from_backup.site, from_backup.ts, from_backup.max_age)
        if kw.get("needs_site_admin"):
            kw.setdefault("admin_factory", lambda: self._c.sites.admin(server, site))
        return provision.provision_site(pilot=pilot, central=central, journal=journal or _journal(),
                                        site=site, from_backup=from_backup, **kw)
